    pairs = []
    num_rows = len(grid)
    num_cols = len(grid[0]) if grid else 0
    for c in range(num_cols):
        for r in range(num_rows - 1):
            if grid[r][c] == grid[r+1][c] and grid[r][c] in [2, 3]:  # Only colors 2 and 3
                pairs.append((r, c, grid[r][c]))
    return pairs

